insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 1, 'Why do beans, pucks, and cleaning balls come before you start milk cleaning?', '["So the visit is shorter on paper","Touching the Cameo (bean lid, puck bin, or the top for cleaning balls) aborts the cleaning and it has to restart","Those steps only work during the cleaning","The milk tubes have to be on the bags first"]'::jsonb, 1, 'Touching the Cameo during the cleaning aborts it. Do the prep first. The cleaning is about 11 minutes.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 2, 'How long is the Cameo milk cleaning at Sinai?', '["About 9 minutes","About 11 minutes","About 48 minutes","Until the bag is empty"]'::jsonb, 1, 'Sinai Series 3.5 is about 11 minutes. RBC Series 5 is about 18. UofT is about 9.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 3, 'What should you do once the cleaning has started?', '["Stand and watch the Cameo the whole time","Be as productive as possible, and aim to finish the other tasks close to when the cleaning is done","Lift the bean lid so you can refill during the cycle","Exit maintenance mode right away"]'::jsonb, 1, 'Use the cleaning time to do the other tasks. Finish close to when it is done.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 4, 'During milk cleaning, what is true about the milk?', '["Do not change bags until the cleaning is finished","You can change milk bags and top up milk, but do not touch the tubes","Pull the tubes out and rinse them","Oat milk is not used at Sinai"]'::jsonb, 1, 'The tubes are in the hot water and Everclean container. You can change bags and top up. Don''t touch the tubes.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 5, 'What happens if the three powder spouts are left facing up?', '["The drinks are sweeter","Powder drinks come out as plain hot water","The Cameo will not start","The door will not close"]'::jsonb, 1, 'All three spouts go back to down-facing, or powder drinks come out as hot water.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 6, 'When do you have the test drink?', '["Before maintenance mode","During milk cleaning","Last, after you exit maintenance mode","Whenever the line is short"]'::jsonb, 2, 'The test drink is the last thing before you leave, after maintenance mode is off.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 7, 'What is true about the service doors?', '["The space is the same while servicing and while a drink is made","When a drink is made, the door slides down and there is less space at the top. Don''t stack items into the door path","Door clearance is only a 2.2 step","Stack cups high so they are easy to reach"]'::jsonb, 1, 'The door slides down to the customer opening. A blocked door takes the kiosk out of service and can break the door.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 8, 'How do you wipe the robot claw?', '["Scrub with a dry pad","Very hot water on a towel, press lightly. Don''t scrub and don''t push","Skip it unless someone complains","Only after arm calibration, with firm pressure"]'::jsonb, 1, 'The arm and claw are very sensitive to pressure and easy to knock off calibration.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 9, 'When are arm calibration and the arm sensor check done?', '["Every visit, after maintenance mode","Weekly, early in the visit, before maintenance mode","Only on show days","Monthly, during milk cleaning"]'::jsonb, 1, 'They are weekly and cannot be done in maintenance mode, so they come first.', true
from public.models m where m.code = 's35';

insert into public.quiz_questions (model_id, position, prompt, choices, answer_index, explanation, draft)
select m.id, 10, 'What do you do on the arm sensor check for now?', '["Fail the visit if you are unsure","Pass it when the location sensors stay solid green","The pass/fail criteria are not confirmed yet. Note what you see","Skip the step until next season"]'::jsonb, 2, 'Albert Kim at KioCafe has not confirmed the pass/fail criteria. Do not invent a pass. Note what you see.', true
from public.models m where m.code = 's35';

